// 二分搜尋最大的 r，使 r² ≤ x
// 時間複雜度: O(log x)，空間複雜度: O(1)
function mySqrt(x) {
    let lo = 0, hi = x;
    while (lo < hi) {
        const mid = Math.floor((lo + hi + 1) / 2); // 向上取中點，避免死循環
        if (mid * mid <= x)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}

