class Solution:
    def mySqrt(self, x: int) -> int:
        """
        方法一：二分搜尋
        時間複雜度: O(log x)
        空間複雜度: O(1)
        """
        if x == 0:
            return 0

        left, right = 1, x

        while left <= right:
            mid = left + (right - left) // 2

            # 避免溢位：mid * mid > x 改為 mid > x / mid
            if mid <= x // mid:
                left = mid + 1
            else:
                right = mid - 1

        return right

    def mySqrt_v2(self, x: int) -> int:
        """
        方法一：二分搜尋（使用 long）
        """
        if x == 0:
            return 0

        left, right = 1, x

        while left <= right:
            mid = left + (right - left) // 2
            square = mid * mid

            if square == x:
                return mid
            elif square < x:
                left = mid + 1
            else:
                right = mid - 1

        return right

    def mySqrt_newton(self, x: int) -> int:
        """
        方法二：牛頓迭代法
        時間複雜度: O(log x)
        空間複雜度: O(1)
        """
        if x == 0:
            return 0

        # 初始猜測
        r = x

        while r > x // r:
            # 牛頓公式
            r = (r + x // r) // 2

        return r

