class Solution {
    /**
     * 方法一：二分搜尋
     * 時間複雜度: O(log x)
     * 空間複雜度: O(1)
     */
    public int mySqrt(int x) {
        if (x == 0) return 0;

        long left = 1, right = x;

        while (left <= right) {
            long mid = left + (right - left) / 2;
            long square = mid * mid;

            if (square == x) {
                return (int) mid;
            } else if (square < x) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }

        return (int) right;
    }

    /**
     * 方法二：牛頓迭代法
     * 時間複雜度: O(log x)
     * 空間複雜度: O(1)
     */
    public int mySqrt_newton(int x) {
        if (x == 0) return 0;

        long r = x;

        while (r > x / r) {
            r = (r + x / r) / 2;
        }

        return (int) r;
    }
}

